INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v2_011', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v2_011","link":null},"plain_text":"insp_std_v2_011","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"air_quality"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Post-handover formaldehyde retest at month 3 and month 6 (formaldehydeCN-text)","link":null},"plain_text":"Post-handover formaldehyde retest at month 3 and month 6 (formaldehydeCN-text)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Repeat GB 50325 Class I sampling at month 3 and month 6 post-handover; formaldehyde ≤ 0.07 mg/m³ each retest; TVOC ≤ 0.45 mg/m³; if either retest fails, isolate the high-emission source (typicallyCN-text furniture / textiles) and re-treat.","link":null},"plain_text":"Repeat GB 50325 Class I sampling at month 3 and month 6 post-handover; formaldehyde ≤ 0.07 mg/m³ each retest; TVOC ≤ 0.45 mg/m³; if either retest fails, isolate the high-emission source (typicallyCN-text furniture / textiles) and re-treat.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[]},"source_authority":{"type":"select","select":{"name":"GB 50325-2020"}},"source_url":{"type":"url","url":"https://www.mohurd.gov.cn/gongkai/zc/wjk/art/2020/art_17339_245708.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"formaldehyde rebound to 0.12 mg/m³ at month 3 after new wardrobe delivery"},{"name":"single pre-move-in test under-detected slow-release peak"},{"name":"retest skipped — owner discovered exceedance via independent testing"}]},"maps_to_server":{"type":"select","select":{"name":"google_calendar"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Schedule month-3 and month-6 third-party air retests; record results and trigger source-isolation workflow on any exceedance.","link":null},"plain_text":"Schedule month-3 and month-6 third-party air retests; record results and trigger source-isolation workflow on any exceedance.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v2_012', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v2_012","link":null},"plain_text":"insp_std_v2_012","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"air_quality"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Indoor air report integrity — per-pollutant breakdown (testreportCN-text)","link":null},"plain_text":"Indoor air report integrity — per-pollutant breakdown (testreportCN-text)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Third-party report shall list each of the 7 GB 50325-2020 pollutants separately (radon, formaldehyde, benzene, toluene, xylene, ammonia, TVOC) with sampling location, instrument model, and calibration date; reports that show only a ''composite'' TVOC pass are rejected.","link":null},"plain_text":"Third-party report shall list each of the 7 GB 50325-2020 pollutants separately (radon, formaldehyde, benzene, toluene, xylene, ammonia, TVOC) with sampling location, instrument model, and calibration date; reports that show only a ''composite'' TVOC pass are rejected.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"GB 50325-2020"}},"source_url":{"type":"url","url":"https://www.mohurd.gov.cn/gongkai/zc/wjk/art/2020/art_17339_245708.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"report aggregates benzene/toluene/xylene under ''TVOC'' line — masksCN-text exceedance"},{"name":"no instrument calibration date"},{"name":"sampling location not specified per room"}]},"map