INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v2_013', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v2_013","link":null},"plain_text":"insp_std_v2_013","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"gas"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Gas-pipe alteration recommissioning by gas-company technician (CN-text)","link":null},"plain_text":"Gas-pipe alteration recommissioning by gas-company technician (CN-text)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Any modification of gas piping, including length extension, fitting replacement, or appliance hookup, completed by gas-company-licensed technician; gas-company recommissioning test (pressure-hold + soap-bubble leak check) passed with written certificate; renovation contractor may not self-certify gas work.","link":null},"plain_text":"Any modification of gas piping, including length extension, fitting replacement, or appliance hookup, completed by gas-company-licensed technician; gas-company recommissioning test (pressure-hold + soap-bubble leak check) passed with written certificate; renovation contractor may not self-certify gas work.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"CJJ 12-2013"}},"source_url":{"type":"url","url":"https://www.mohurd.gov.cn/gongkai/zc/wjk/art/2013/art_17339_216051.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"renovation crew altered gas pipe without gas-company involvement"},{"name":"no leak-test certificate after stove install"},{"na