INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v2_014', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v2_014","link":null},"plain_text":"insp_std_v2_014","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"central_air"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Central a/c condensate drain slope verification before ceiling closure (midCN-termHVACcondensateCN-text)","link":null},"plain_text":"Central a/c condensate drain slope verification before ceiling closure (midCN-termHVACcondensateCN-text)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Condensate drain runs with continuous slope ≥1% toward discharge; slow-pour test of 500 mL clears the line within 60 s; no reverse-slope segment between indoor unit and discharge; insulated drain pipe to prevent condensation drip onto ceiling.","link":null},"plain_text":"Condensate drain runs with continuous slope ≥1% toward discharge; slow-pour test of 500 mL clears the line within 60 s; no reverse-slope segment between indoor unit and discharge; insulated drain pipe to prevent condensation drip onto ceiling.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"video"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"GB 50736-2012"}},"source_url":{"type":"url","url":"https://www.mohurd.gov.cn/gongkai/zc/wjk/art/2012/art_17339_214184.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"condensate drain reverse-slope appeared as ceiling stain at month 4"},{"name":"drain pipe not insulated — drip onto gypsum ceiling"},{"name":"indoor-unit lift kit drain trap missing"}]},"maps_to_s