INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v3_001', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v3_001","link":null},"plain_text":"insp_std_v3_001","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"contract"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Vendor financial-health verification before signing main contract (fit-outcompanyCN-text/CN-textriskCN-text)","link":null},"plain_text":"Vendor financial-health verification before signing main contract (fit-outcompanyCN-text/CN-textriskCN-text)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before signing, the owner verifies the vendor''s public business records: (a) CN-textsystem CN-text in active status; (b) no CN-textline / CN-textlinepeople listing against the legal representative; (c) no abnormal-operations or major dissolution filing in the prior 12 months; (d) no concentrated CN-textcomplaint cluster (>30 unresolved in trailing 6 months) for CN-text / CN-text / midCN-text keywords; (e) registered capital paid-in covers at least 12 months of the project deposit; results captured in a one-page risk memo signed by owner.","link":null},"plain_text":"Before signing, the owner verifies the vendor''s public business records: (a) CN-textsystem CN-text in active status; (b) no CN-textline / CN-textlinepeople listing against the legal representative; (c) no abnormal-operations or major dissolution filing in the prior 12 months; (d) no concentrated CN-textcomplaint cluster (>30 unresolved in trailing 6 months) for CN-text / CN-text / midCN-text keywords; (e) registered capital paid-in covers at least 12 months of the project deposit; results captured in a one-page risk memo signed by owner.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"written_owner_signoff"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"pre_demolition"},{"name":"rough_in"},{"name":"tile"},{"name":"cabinet"},{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"consumer_protection_2025"}},"source_url":{"type":"url","url":"https://www.gsxt.gov.cn/"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"large CN-textresidential renovation platform collapsed mid-project with 800+ unfinished sites — owner had paid 60% deposit"},{"name":"regional residential renovation vendor with 68 affected households and ¥1.6M+ deposits lost — no pre-sign credit check"},{"name":"vendor legal representative on CN-text list — owner not aware until after contract signed"}]},"maps_to_server":{"type":"select","select":{"name":"visa_and_advisory"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Block main-contract signing and any deposit transfer until the risk memo is signed; re-run the check every 60 days for projects with phased payment schedules.","link":null},"plain_text":"Block main-contract signing and any deposit transfer until the risk memo is signed; re-run the check every 60 days for projects with phased payment schedules.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v3_002', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v3_002","link":null},"plain_text":"insp_std_v3_002","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"contract"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Third-party fund-escrow account with phase-release gates (fit-outCN-termNo.CN-text)","link":null},"plain_text":"Third-party fund-escrow account with phase-release gates (fit-outCN-termNo.CN-text)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"All payments above ¥10,000 routed through a third-party bank-escrow account (e.g., platform firstfit-outafterpayment model) rather than direct transfer to the vendor; release schedule tied to written acceptance gates: 30% after demolition+rough-in acceptance, 30% after waterproofing+concealed-works acceptance, 25% after tile+cabinet acceptance, 10% after final-handover acceptance, 5% retained for 6-month warranty; release at each gate requires owner signature, not vendor self-certification.","link":null},"plain_text":"All payments above ¥10,000 routed through a third-party bank-escrow account (e.g., platform firstfit-outafterpayment model) rather than direct transfer to the vendor; release schedule tied to written acceptance gates: 30% after demolition+rough-in acceptance, 30% after waterproofing+concealed-works acceptance, 25% after tile+cabinet acceptance, 10% after final-handover acceptance, 5% retained for 6-month warranty; release at each gate requires owner signature, not vendor self-certification.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"written_owner_signoff"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"pre_demolition"},{"name":"rough_in"},{"name":"waterproofing"},{"name":"tile"},{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"consumer_protection_2025"}},"source_url":{"type":"url","url":"https://www.thepaper.cn/newsDetail_forward_30379632"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"owner paid 70% lump-sum up front — vendor ''disappeared'' before tile work"},{"name":"platform escrow released funds on vendor''s signature without owner approval"},{"name":"no 5% warranty retention — vendor unreachable for 6-month defects"}]},"maps_to_server":{"type":"select","select":{"name":"visa_and_advisory"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Block deposit transfer to vendor''s own account; verify escrow contract is signed before demolition; lock each release gate behind a passing acceptance record.","link":null},"plain_text":"Block deposit transfer to vendor''s own account; verify escrow contract is signed before demolition; lock each release gate behind a passing acceptance record.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v3_003', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v3_003","link":null},"plain_text":"insp_std_v3_003","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"rough_in"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Stage-1 third-party CN-termroomCN-term inspection after water/electrical rough-in (CN-text No.CN-textroom)","link":null},"plain_text":"Stage-1 third-party CN-termroomCN-term inspection after water/electrical rough-in (CN-text No.CN-textroom)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Within 3 days of water+electrical rough-in completion and before any wall closure, an independent licensed CN-termroomCN-term performs a written inspection; standard fee forCN-text 90-120㎡ unit ¥300-480 (¥10/㎡ forCN-textroom); report covers ≥15 categories / ≥33 subitems / ≥420 checkpoints including PPR water pressure test ≥0.8 MPa hold 30 min with zero drop, circuit insulation resistance, conduit separation, conductor sizing per outlet; defects entered into change-order log within 24 h.","link":null},"plain_text":"Within 3 days of water+electrical rough-in completion and before any wall closure, an independent licensed CN-termroomCN-term performs a written inspection; standard fee forCN-text 90-120㎡ unit ¥300-480 (¥10/㎡ forCN-textroom); report covers ≥15 categories / ≥33 subitems / ≥420 checkpoints including PPR water pressure test ≥0.8 MPa hold 30 min with zero drop, circuit insulation resistance, conduit separation, conductor sizing per outlet; defects entered into change-order log within 24 h.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"waterproofing"},{"name":"tile"},{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"industry_practice"}},"source_url":{"type":"url","url":"https://blog.csdn.net/XJWLYF8888/article/details/127134401"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"wall closure done without CN-termroomCN-term visit — concealed joint discovered post-tile, 5× rework cost"},{"name":"water-pressure test only held 5 min instead of 30 min"},{"name":"verbal verbal-only finding not recorded in change-order log"}]},"maps_to_server":{"type":"select","select":{"name":"visa_and_advisory"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Block waterproofing or wall closure until a written Stage-1 CN-termroomCN-term report is filed and defects are scheduled for remediation.","link":null},"plain_text":"Block waterproofing or wall closure until a written Stage-1 CN-termroomCN-term report is filed and defects are scheduled for remediation.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v3_004', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v3_004","link":null},"plain_text":"insp_std_v3_004","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"tile"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Stage-2 third-party CN-termroomCN-term inspection after CN-text completion (CN-text No.CN-textroom)","link":null},"plain_text":"Stage-2 third-party CN-termroomCN-term inspection after CN-text completion (CN-text No.CN-textroom)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Within 3 days of tile + grouting completion and before paint or cabinet install, an independent CN-termroomCN-term performs a tap-test inspection of every tile surface; hollow rate ≤ 5% project-wide and ≤ 15% on any single tile per GB 50210-2018; flatness ≤ 2 mm under 2 m straightedge; closed-water test repeated at 30 mm depth × ≥24 h post-tile; report fee ¥300-480 (CN-text) or ¥10/㎡ (CN-text), with photos + integrated repair list.","link":null},"plain_text":"Within 3 days of tile + grouting completion and before paint or cabinet install, an independent CN-termroomCN-term performs a tap-test inspection of every tile surface; hollow rate ≤ 5% project-wide and ≤ 15% on any single tile per GB 50210-2018; flatness ≤ 2 mm under 2 m straightedge; closed-water test repeated at 30 mm depth × ≥24 h post-tile; report fee ¥300-480 (CN-text) or ¥10/㎡ (CN-text), with photos + integrated repair list.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"paint"},{"name":"cabinet"},{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"industry_practice"}},"source_url":{"type":"url","url":"https://blog.csdn.net/XJWLYF8888/article/details/127134401"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"tile fell from wall at month 5 — never tap-tested before paint"},{"name":"no Stage-2 inspection — flatness defects covered by skirting board"},{"name":"second closed-water test skipped — leak surfaced after move-in"}]},"maps_to_server":{"type":"select","select":{"name":"visa_and_advisory"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Block paint or cabinet install scheduling until the Stage-2 CN-termroomCN-term report is on file and remediation is closed.","link":null},"plain_text":"Block paint or cabinet install scheduling until the Stage-2 CN-termroomCN-term report is on file and remediation is closed.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v3_005', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v3_005","link":null},"plain_text":"insp_std_v3_005","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"air_quality"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"CMA-accredited indoor-air testing timing rule — minimum 7-day post-completion delay + 12-hour closed-window pre-conditioning (CMAtesttimewindow)","link":null},"plain_text":"CMA-accredited indoor-air testing timing rule — minimum 7-day post-completion delay + 12-hour closed-window pre-conditioning (CMAtesttimewindow)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Testing must commence ≥7 calendar days after the last finishing activity (paint, glue, sealant, or new-furniture delivery); doors and windows closed for ≥12 h before sampling for the 3-pollutant panel (formaldehyde + benzene + TVOC), or ≥24 h before sampling for the 5-pollutant panel (adds toluene/xylene/ammonia/radon); air conditioner and ventilation off during the closed period; report turnaround 5-7 days; laboratory must hold valid CMA accreditation with certificate number on report.","link":null},"plain_text":"Testing must commence ≥7 calendar days after the last finishing activity (paint, glue, sealant, or new-furniture delivery); doors and windows closed for ≥12 h before sampling for the 3-pollutant panel (formaldehyde + benzene + TVOC), or ≥24 h before sampling for the 5-pollutant panel (adds toluene/xylene/ammonia/radon); air conditioner and ventilation off during the closed period; report turnaround 5-7 days; laboratory must hold valid CMA accreditation with certificate number on report.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"GB 50325-2020"}},"source_url":{"type":"url","url":"https://www.mohurd.gov.cn/gongkai/zc/wjk/art/2020/art_17339_245708.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"test run within 48 h of paint completion — formaldehyde under-detected (slow-release peak missed)"},{"name":"windows open during 12-h pre-conditioning — TVOC under-reported by ~40%"},{"name":"non-CMA lab used — report rejected by court in subsequent dispute"}]},"maps_to_server":{"type":"select","select":{"name":"visa_and_advisory"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Verify the lab''s CMA certificate number is on the report and sampling timestamp is at least 7 days after the last finishing entry in the construction log; reject otherwise.","link":null},"plain_text":"Verify the lab''s CMA certificate number is on the report and sampling timestamp is at least 7 days after the last finishing entry in the construction log; reject otherwise.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v3_006', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v3_006","link":null},"plain_text":"insp_std_v3_006","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"air_quality"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"CMA sampling-point density per room (CMAtestCN-textdensity)","link":null},"plain_text":"CMA sampling-point density per room (CMAtestCN-textdensity)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Sampling points scaled to floor area per GB 50325-2020: ≤50 m² → 1 point per room; 50-100 m² → 2 points per room; >100 m² → 3-5 points per room; minimum one sample in each enclosed room (bedrooms, living room, kitchen, study); kitchen sampled separately due to combustion sources; sampling point ≥0.5 m from wall, ≥1.0 m above floor, ≥0.5 m from doors and windows; 3-pollutant panel fee ¥1,200 / 100 m² unit, 5-pollutant ¥2,000, per-point ¥500-800.","link":null},"plain_text":"Sampling points scaled to floor area per GB 50325-2020: ≤50 m² → 1 point per room; 50-100 m² → 2 points per room; >100 m² → 3-5 points per room; minimum one sample in each enclosed room (bedrooms, living room, kitchen, study); kitchen sampled separately due to combustion sources; sampling point ≥0.5 m from wall, ≥1.0 m above floor, ≥0.5 m from doors and windows; 3-pollutant panel fee ¥1,200 / 100 m² unit, 5-pollutant ¥2,000, per-point ¥500-800.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"GB 50325-2020"}},"source_url":{"type":"url","url":"https://www.mohurd.gov.cn/gongkai/zc/wjk/art/2020/art_17339_245708.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"whole-unit single-sample report — bedroom exceedance hidden by living-room dilution"},{"name":"kitchen not sampled separately — combustion contributors masked"},{"name":"sampling point next to window — value diluted by infiltration air"}]},"maps_to_server":{"type":"select","select":{"name":"visa_and_advisory"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Reject any indoor-air report that lacks per-room sampling locations or uses fewer than the minimum point count for the unit area.","link":null},"plain_text":"Reject any indoor-air report that lacks per-room sampling locations or uses fewer than the minimum point count for the unit area.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v3_007', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v3_007","link":null},"plain_text":"insp_std_v3_007","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"plumbing"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Public-stack drain-line accessibility — inspection port and removable cabinet panel (CN-textretain)","link":null},"plain_text":"Public-stack drain-line accessibility — inspection port and removable cabinet panel (CN-textretain)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Where renovation encloses a shared/public drainage stack (CN-text) in a cabinet, soffit, or wall built-out, an accessible inspection port (CN-text ≥200 mm × 200 mm with removable cover) must be retained at every required maintenance point per CECS 168; cabinet panel over a stack must be screw-fixed (not glued) and labeled with a permanent tag indicating ''public drainage — do not seal''; owner signs an acknowledgment that refusal to allow stack access during a downstairs leak event shifts joint-and-several liability for downstream damage.","link":null},"plain_text":"Where renovation encloses a shared/public drainage stack (CN-text) in a cabinet, soffit, or wall built-out, an accessible inspection port (CN-text ≥200 mm × 200 mm with removable cover) must be retained at every required maintenance point per CECS 168; cabinet panel over a stack must be screw-fixed (not glued) and labeled with a permanent tag indicating ''public drainage — do not seal''; owner signs an acknowledgment that refusal to allow stack access during a downstairs leak event shifts joint-and-several liability for downstream damage.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"written_owner_signoff"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"tile"},{"name":"cabinet"},{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"shanghai_court_2024"}},"source_url":{"type":"url","url":"https://hshfy.sh.cn/shfy/web/xxnr.jsp"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"3rd-floor unit suffered ¥39,000+ ceiling damage from 4th-floor public stack leak; 4th-floor owner refused cabinet removal for inspection — court apportioned 50% liability to that owner"},{"name":"stack enclosed without inspection port — plumber chiseled tile to access, owner billed for restoration"},{"name":"tag missing — next owner / property manager sealed the access during refit"}]},"maps_to_server":{"type":"select","select":{"name":"notion"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Block tile/cabinet sign-off if a public-stack inspection port is missing or not labeled; record owner acknowledgment in the handover packet.","link":null},"plain_text":"Block tile/cabinet sign-off if a public-stack inspection port is missing or not labeled; record owner acknowledgment in the handover packet.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v3_008', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v3_008","link":null},"plain_text":"insp_std_v3_008","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"waterproofing"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"30-day post-handover closed-water re-test (CN-text 30dayCN-textretest)","link":null},"plain_text":"30-day post-handover closed-water re-test (CN-text 30dayCN-textretest)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"At day 30 ±3 post-handover, repeat the closed-water test (≥30 mm water depth × ≥24 h) in every wet area; downstairs unit ceiling re-inspected on the same day in coordination with downstairs owner; test passes only if (a) water-level drop is explained by evaporation alone, (b) downstairs ceiling has no new stain or moisture spot, (c) no efflorescence at floor-wall joints in the tested room.","link":null},"plain_text":"At day 30 ±3 post-handover, repeat the closed-water test (≥30 mm water depth × ≥24 h) in every wet area; downstairs unit ceiling re-inspected on the same day in coordination with downstairs owner; test passes only if (a) water-level drop is explained by evaporation alone, (b) downstairs ceiling has no new stain or moisture spot, (c) no efflorescence at floor-wall joints in the tested room.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"test_report"}},"blocks_next_phases":{"type":"multi_select","multi_select":[]},"source_authority":{"type":"select","select":{"name":"shanghai_court_2024"}},"source_url":{"type":"url","url":"https://hshfy.sh.cn/shfy/web/xxnr.jsp"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"initial closed-water test passed at handover but month-1 retest showed downstairs ceiling damp spot — vendor disputed liability without month-1 evidence"},{"name":"drainage-pipe leak masked by floor void — surfaced only after 30 days of normal use"},{"name":"downstairs owner refused day-30 access — leak progressed to month-3 and damages compounded"}]},"maps_to_server":{"type":"select","select":{"name":"google_calendar"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Auto-schedule a day-30 closed-water retest on the calendar at handover; record results in the warranty register and pursue immediate remediation on any positive.","link":null},"plain_text":"Auto-schedule a day-30 closed-water retest on the calendar at handover; record results in the warranty register and pursue immediate remediation on any positive.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v3_009', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v3_009","link":null},"plain_text":"insp_std_v3_009","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"waterproofing"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"90-day post-handover closed-water + drainage inspection (CN-text+CN-text90dayCN-text)","link":null},"plain_text":"90-day post-handover closed-water + drainage inspection (CN-text+CN-text90dayCN-text)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"At day 90 ±7 post-handover, repeat closed-water test in shower zones (≥24 h hold) AND perform a 30-minute high-volume drainage stress test (run shower + sink + floor drain simultaneously at full flow) while downstairs ceiling is observed; record any anomaly in the warranty register; failure triggers root-cause analysis covering (a) waterproofing membrane integrity, (b) public-stack joint, (c) floor-tile grout permeability, (d) sealant aging.","link":null},"plain_text":"At day 90 ±7 post-handover, repeat closed-water test in shower zones (≥24 h hold) AND perform a 30-minute high-volume drainage stress test (run shower + sink + floor drain simultaneously at full flow) while downstairs ceiling is observed; record any anomaly in the warranty register; failure triggers root-cause analysis covering (a) waterproofing membrane integrity, (b) public-stack joint, (c) floor-tile grout permeability, (d) sealant aging.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"test_report"}},"blocks_next_phases":{"type":"multi_select","multi_select":[]},"source_authority":{"type":"select","select":{"name":"shanghai_court_2024"}},"source_url":{"type":"url","url":"https://hshfy.sh.cn/shfy/web/xxnr.jsp"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"leak surfaced at month 3 — root cause was public-stack joint, not unit waterproofing, but no inspection-port access caused 2-week diagnostic delay"},{"name":"shower drain accumulated hair clog — drainage stress test would have surfaced at month 1"},{"name":"downstairs ceiling stain appeared at month 4 — no day-90 record to anchor warranty claim"}]},"maps_to_server":{"type":"select","select":{"name":"google_calendar"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Auto-schedule a day-90 closed-water + drainage stress test on the calendar; require downstairs owner present or remote-video confirmation.","link":null},"plain_text":"Auto-schedule a day-90 closed-water + drainage stress test on the calendar; require downstairs owner present or remote-video confirmation.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v3_010', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v3_010","link":null},"plain_text":"insp_std_v3_010","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"contract"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Quote benchmarking against 2025 Shanghai market reference bands (quoteCN-text)","link":null},"plain_text":"Quote benchmarking against 2025 Shanghai market reference bands (quoteCN-text)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before signing, owner cross-checks the vendor''s quote against 2025 Shanghai market reference bands: CN-textfit-out ¥500-800/㎡; midCN-termfit-out ¥1,000-1,500/㎡; CN-text (peopleCN-term+CN-text) ¥1,100-1,500/㎡; CN-text (peopleCN-term+CN-text+finish materials) ¥1,800-2,500/㎡ (mid ¥1,400-2,000/㎡); highCN-text ¥3,000-5,000/㎡; quotes >25% above the upper band of the applicable tier require itemized justification; quotes >15% below the lower band trigger a hidden-add-on risk flag (typical CN-text rate 42%, with CN-text 60%+ of overruns).","link":null},"plain_text":"Before signing, owner cross-checks the vendor''s quote against 2025 Shanghai market reference bands: CN-textfit-out ¥500-800/㎡; midCN-termfit-out ¥1,000-1,500/㎡; CN-text (peopleCN-term+CN-text) ¥1,100-1,500/㎡; CN-text (peopleCN-term+CN-text+finish materials) ¥1,800-2,500/㎡ (mid ¥1,400-2,000/㎡); highCN-text ¥3,000-5,000/㎡; quotes >25% above the upper band of the applicable tier require itemized justification; quotes >15% below the lower band trigger a hidden-add-on risk flag (typical CN-text rate 42%, with CN-text 60%+ of overruns).","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"written_owner_signoff"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"pre_demolition"},{"name":"rough_in"},{"name":"tile"},{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"industry_practice"}},"source_url":{"type":"url","url":"https://www.163.com/dy/article/K7J9B3L30556EG2C.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"CN-text quote at ¥1,200/㎡ — final cost ¥2,400/㎡ via 38% CN-text, mostly CN-text and CN-text"},{"name":"CN-text not recorded — owner unable to challenge peak season +8% premium atCN-text"},{"name":"main-material upgrades ''recommended'' then forced — owner paid 22% above signed price"}]},"maps_to_server":{"type":"select","select":{"name":"visa_and_advisory"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Verify a signed benchmark-comparison sheet exists in the contract packet; flag any CN-text ratio at completion that exceeds 15% of the original contract value for owner-vendor reconciliation.","link":null},"plain_text":"Verify a signed benchmark-comparison sheet exists in the contract packet; flag any CN-text ratio at completion that exceeds 15% of the original contract value for owner-vendor reconciliation.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v3_011', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v3_011","link":null},"plain_text":"insp_std_v3_011","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"contract"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Seasonal-premium and labor-availability disclosure (CN-textprice+scheduleCN-text)","link":null},"plain_text":"Seasonal-premium and labor-availability disclosure (CN-textprice+scheduleCN-text)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Contract explicitly discloses: (a) base period vs peak-season (May, September) labor premium (typical +5-8% over base); (b) any post-Spring-Festival start-up queue (typical 4-8 weeks); (c) committed start date with named project manager; (d) penalty clause for vendor-side delay beyond 14 days at ≥0.05% of contract value per day; quote that omits any of these triggers a contract-revision request before signing.","link":null},"plain_text":"Contract explicitly discloses: (a) base period vs peak-season (May, September) labor premium (typical +5-8% over base); (b) any post-Spring-Festival start-up queue (typical 4-8 weeks); (c) committed start date with named project manager; (d) penalty clause for vendor-side delay beyond 14 days at ≥0.05% of contract value per day; quote that omits any of these triggers a contract-revision request before signing.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"written_owner_signoff"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"pre_demolition"},{"name":"rough_in"}]},"source_authority":{"type":"select","select":{"name":"industry_practice"}},"source_url":{"type":"url","url":"https://www