INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('insp_std_v3_012', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"insp_std_v3_012","link":null},"plain_text":"insp_std_v3_012","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"final_handover"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Stage-3 third-party CN-termroomCN-term inspection before final handover (CN-textbefore No.CN-textroom)","link":null},"plain_text":"Stage-3 third-party CN-termroomCN-term inspection before final handover (CN-textbefore No.CN-textroom)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Within 7 days before the scheduled final-handover signing, an independent CN-termroomCN-term performs a complete pre-handover inspection covering 15 major + 33 sub-categories per industry guideline; minimum scope includes air-quality, water-pressure 0.8 MPa × 30 min, closed-water ≥24 h, tile tap-test, electrical RCD trip-time, drainage stress test, and Shanghai-specific damp-proofing checks; fee ¥10/㎡ for CN-textroom or ¥300-480 fixed forCN-text 90-150 ㎡; report incorporates Stage-1 and Stage-2 findings and closes them or escalates them to warranty register.","link":null},"plain_text":"Within 7 days before the scheduled final-handover signing, an independent CN-termroomCN-term performs a complete pre-handover inspection covering 15 major + 33 sub-categories per industry guideline; minimum scope includes air-quality, water-pressure 0.8 MPa × 30 min, closed-water ≥24 h, tile tap-test, electrical RCD trip-time, drainage stress test, and Shanghai-specific damp-proofing checks; fee ¥10/㎡ for CN-textroom or ¥300-480 fixed forCN-text 90-150 ㎡; report incorporates Stage-1 and Stage-2 findings and closes them or escalates them to warranty register.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"industry_practice"}},"source_url":{"type":"url","url":"https://blog.csdn.net/XJWLYF8888/article/details/127134401"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"only Stage-3 inspection performed — concealed defects from earlier phases already covered"},{"name":"vendor self-inspection report substituted — bias toward leniency"},{"name":"report missing Shanghai-specific CN-text checks despite humid climate"}]},"maps_to_server":{"type":"select","select":{"name":"visa_and_advisory"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Block final-payment release until the Stage-3 written report is filed and all Stage-1/Stage-2 carry-over items are closed or assigned to warranty.","link":null},"plain_text":"Block final-payment release until the Stage-3 written report is filed and all Stage-1/Stage-2 carry-over items are closed or assigned to warranty.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
