INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_property_003', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_property_003","link":null},"plain_text":"rule_property_003","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"national"}},"topic":{"type":"select","select":{"name":"waterproofing"}},"authority_level":{"type":"select","select":{"name":"national_ministry"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Converting a room or balcony that has no waterproofing requirement into a bathroom or kitchen is prohibited.","link":null},"plain_text":"Converting a room or balcony that has no waterproofing requirement into a bathroom or kitchen is prohibited.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Keep wet-area locations to rooms originally designed as wet areas; otherwise require a qualified design review.","link":null},"plain_text":"Keep wet-area locations to rooms originally designed as wet areas; otherwise require a qualified design review.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before scope freeze","link":null},"plain_text":"Before scope freeze","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Order to restore + downstream water-damage liability to neighbors.","link":null},"plain_text":"Order to restore + downstream water-damage liability to neighbors.","annotations":{},"href":null}]},"maps_to_server":{"type":"select","select":{"name":"notion"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Flag any plan that moves a bathroom or kitchen to a balcony / non-wet room without a qualified design note.","link":null},"plain_text":"Flag any plan that moves a bathroom or kitchen to a balcony / non-wet room without a qualified design note.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.gov.cn/gongbao/content/2003/content_62197.htm"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"CN-textwithindecoration and renovationCN-text Art. 5(2)","link":null},"plain_text":"CN-textwithindecoration and renovationCN-text Art. 5(2)","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_property_004', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_property_004","link":null},"plain_text":"rule_property_004","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"national"}},"topic":{"type":"select","select":{"name":"gas"}},"authority_level":{"type":"select","select":{"name":"national_ministry"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Modifying gas pipes or fixtures during renovation requires prior approval from the gas management unit.","link":null},"plain_text":"Modifying gas pipes or fixtures during renovation requires prior approval from the gas management unit.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Engage the city gas company; obtain written approval; only licensed gas installers may touch the pipework.","link":null},"plain_text":"Engage the city gas company; obtain written approval; only licensed gas installers may touch the pipework.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before any kitchen rough-in that touches the gas line","link":null},"plain_text":"Before any kitchen rough-in that touches the gas line","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Order to restore + safety risk; insurance void.","link":null},"plain_text":"Order to restore + safety risk; insurance void.","annotations":{},"href":null}]},"maps_to_server":{"type":"select","select":{"name":"visa_and_advisory"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Verify a gas-company approval record exists before kitchen rough-in is scheduled.","lin