INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_property_006', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_property_006","link":null},"plain_text":"rule_property_006","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"noise_hours"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"In Shanghai residential communities, noisy operations (knocking, chiseling, sawing, drilling) are prohibited from 18:00 to 08:00 daily and all day on statutory holidays.","link":null},"plain_text":"In Shanghai residential communities, noisy operations (knocking, chiseling, sawing, drilling) are prohibited from 18:00 to 08:00 daily and all day on statutory holidays.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Schedule noisy work strictly between 08:00 and 18:00 on non-holiday workdays / weekends; quiet activities (cleaning, measurement, delivery) may run outside.","link":null},"plain_text":"Schedule noisy work strictly between 08:00 and 18:00 on non-holiday workdays / weekends; quiet activities (cleaning, measurement, delivery) may run outside.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Daily, throughout construction","link":null},"plain_text":"Daily, throughout construction","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Property warning; neighbor complaint escalation; ordered stoppage.","link":null},"plain_text":"Property warning; neighbor complaint escalation; ordered stoppage.","annotations":{},"href":null}]},"maps_to_server":{"type":"select","select":{"name":"google_calendar"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Reject any calendar event tagged as demolition / drilling / chiseling that runs outside 08:00-18:00 or on a statutory holiday.","link":null},"plain_text":"Reject any calendar event tagged as demolition / drilling / chiseling that runs outside 08:00-18:00 or on a statutory holiday.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shanghai.gov.cn/gwk/search/content/a03420d81639493db42343592087bb91"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"CN-termroomCN-text〔2024〕1No. CN-textproperty managementserviceCN-textlineCN-textfit-outCN-textofnotice","link":null},"plain_text":"CN-termroomCN-text〔2024〕1No. CN-textproperty managementserviceCN-textlineCN-textfit-outCN-textofnotice","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_property_007', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_property_007","link":null},"plain_text":"rule_property_007","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"filing"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before renovation registration, the owner must submit the decoration contractor, construction period, and construction drawings / plan to property management.","link":null},"plain_text":"Before renovation registration, the owner must submit the decoration contractor, construction period, and construction drawings / plan to property management.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Prepare a packet with: contractor business license / qualifications, construction period, drawings, and signed decoration agreement; submit to property.","link":null},"plain_text":"Prepare a packet with: contractor business license / qualifications, construction period, drawings, and signed decoration agreement; submit to property.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before construction starts","link":null},"plain_text":"Before construction starts","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Property may refuse to issue construction pass; workers / materials denied entry.","link":null},"plain_text":"Property may refuse to issue construction pass; workers / materials denied entry.","annotations":{},"href":null}]},"maps_to_server"