INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_property_009', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_property_009","link":null},"plain_text":"rule_property_009","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"neighbor_notice"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Property must inspect renovation sites daily; unresolved non-compliance must be reported to the housing administration within 24 hours.","link":null},"plain_text":"Property must inspect renovation sites daily; unresolved non-compliance must be reported to the housing administration within 24 hours.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Maintain a communication log with property; respond to property warning notes within the same day to avoid escalation.","link":null},"plain_text":"Maintain a communication log with property; respond to property warning notes within the same day to avoid escalation.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Within 24 hours of any property warning","link":null},"plain_text":"Within 24 hours of any property warning","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Escalation to housing authority; construction pass revoked.","link":null},"plain_text":"Escalation to housing authority; construction pass revoked.","annotations":{},"href":null}]},"maps_to_server":{"type":"select","select":{"name":"emails"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"conten