INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_property_010', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_property_010","link":null},"plain_text":"rule_property_010","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"waste"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Renovation waste must be collected separately from household garbage; bagged placement and hazardous-material separation are required.","link":null},"plain_text":"Renovation waste must be collected separately from household garbage; bagged placement and hazardous-material separation are required.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Arrange bagged collection and a separate renovation-waste pickup; do not mix with general bins.","link":null},"plain_text":"Arrange bagged collection and a separate renovation-waste pickup; do not mix with general bins.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Throughout construction","link":null},"plain_text":"Throughout construction","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Fines ¥100-¥1,000; pickup refused.","link":null},"plain_text":"Fines ¥100-¥1,000; pickup refused.","annotations":{},"href":null}]},"maps_to_server":{"type":"select","select":{"name":"notion"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Verify a separate waste-hauling vendor / arrangement exists; flag any plan that disposes renovation waste via household bins.","link":nu