INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_property_017', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_property_017","link":null},"plain_text":"rule_property_017","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"noise_hours"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Statutory holidays (CN-textstatutory holiday, excluding weekends) prohibit noisy construction work all day.","link":null},"plain_text":"Statutory holidays (CN-textstatutory holiday, excluding weekends) prohibit noisy construction work all day.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Block out statutory holiday dates on the construction calendar; only quiet tasks may occur.","link":null},"plain_text":"Block out statutory holiday dates on the construction calendar; only quiet tasks may occur.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Each statutory holiday during the project","link":null},"plain_text":"Each statutory holiday during the project","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Property stoppage; neighbor complaint.","link":null},"plain_text":"Property stoppage; neighbor complaint.","annotations":{},"href":null}]},"maps_to_server":{"type":"select","select":{"name":"google_calendar"}},"checker_use":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Reject any noisy calendar event scheduled on a statutory holiday.","link":null},"plain_text":"Reject any noisy calendar event scheduled on 