INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_property_v2_001', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_property_v2_001","link":null},"plain_text":"rule_property_v2_001","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal_2024"}},"topic":{"type":"select","select":{"name":"filing"}},"authority_level":{"type":"select","select":{"name":"municipal_gov_2024"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"From 2024-07-01, property must verify the identity of every renovation worker entering the community; unidentified workers are denied entry.","link":null},"plain_text":"From 2024-07-01, property must verify the identity of every renovation worker entering the community; unidentified workers are denied entry.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Have the contractor submit a worker roster with ID copies to property before mobilization; ensure each worker is registered at the property gate on arrival.","link":null},"plain_text":"Have the contractor submit a worker roster with ID copies to property before mobilization; ensure each worker is registered at the property gate on arrival.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before each new worker first enters the site","link":null},"plain_text":"Before each new worker first enters the site","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Worker turned away at gate; schedule slippage; property must report unresolved issues to housing authority within 24h.","link":null},"plain_text":"Worker turned away at gate; schedule slippage; property must report