INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_property_v2_007', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_property_v2_007","link":null},"plain_text":"rule_property_v2_007","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal_2024"}},"topic":{"type":"select","select":{"name":"noise_enforcement"}},"authority_level":{"type":"select","select":{"name":"municipal_gov_2024"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Renovation noise is a key target under the 2024-2026 noise-pollution action plan; pilot communities may install smart noise-monitoring devices with automated alerts.","link":null},"plain_text":"Renovation noise is a key target under the 2024-2026 noise-pollution action plan; pilot communities may install smart noise-monitoring devices with automated alerts.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Check whether the project''s community is on the pilot list; if yes, expect data-driven enforcement (no human inspector needed) and tighten internal compliance.","link":null},"plain_text":"Check whether the project''s community is on the pilot list; if yes, expect data-driven enforcement (no human inspector needed) and tighten internal compliance.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Project-onset due-diligence","link":null},"plain_text":"Project-onset due-diligence","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Automated alerts trigger property warning; pattern of breaches escalated to district.","link":null},"plain_text":"Automated alerts trigger property warning; pattern of breaches es