INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_property_v2_008', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_property_v2_008","link":null},"plain_text":"rule_property_v2_008","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal_2024"}},"topic":{"type":"select","select":{"name":"noise_enforcement"}},"authority_level":{"type":"select","select":{"name":"municipal_gov_2024"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Residential noise violations follow a complaint pathway: resident complaint -> CN-text/CN-text/property management confirmation -> public security warning -> repeat offense fined 200-500 CNY. CN-text may set stricter rules than municipal.","link":null},"plain_text":"Residential noise violations follow a complaint pathway: resident complaint -> CN-text/CN-text/property management confirmation -> public security warning -> repeat offense fined 200-500 CNY. CN-text may set stricter rules than municipal.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"On any neighbor complaint, immediately pause noisy work, document the timestamp, and reply to property in writing the same day.","link":null},"plain_text":"On any neighbor complaint, immediately pause noisy work, document the timestamp, and reply to property in writing the same day.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Same-day on any complaint","link":null},"plain_text":"Same-day on any complaint","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"200-500 CNY fine on repeat offense; pattern of complaints can revoke construction pass.","link":null},"