INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_property_v2_009', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_property_v2_009","link":null},"plain_text":"rule_property_v2_009","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"district_pudong"}},"topic":{"type":"select","select":{"name":"online_filing"}},"authority_level":{"type":"select","select":{"name":"district_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Pudong residents can file renovation registration, book waste pickup, and submit noise complaints through the district one-stop filing online platform in a single transaction.","link":null},"plain_text":"Pudong residents can file renovation registration, book waste pickup, and submit noise complaints through the district one-stop filing online platform in a single transaction.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"If the property is in Pudong, complete the filing online via the one-stop filing portal before construction; save the digital receipt.","link":null},"plain_text":"If the property is in Pudong, complete the filing online via the one-stop filing portal before construction; save the digital receipt.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before construction starts","link":null},"plain_text":"Before construction starts","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"In-person filing also accepted but slower; missing receipt blocks waste-pickup booking.","link":null},"plain_text":"In-person filing also accepted but slower; missing receipt blocks waste-pickup booking.","annotations":{},"href":nu